{
  "packet_id": "H6-T03-1",
  "claim_id": "C042",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C042.component",
    "value": "A population failure rate must not be inferred from the 14-of-90 sample result without a defensible sampling basis.",
    "scope": "A necessary condition on population extrapolation; a sampling basis is not asserted to be sufficient, and missing attachments are not reclassified as approval failures.",
    "provenance": {
      "refs": [
        {
          "source_id": "P028",
          "role": "SUPPORT"
        },
        {
          "source_id": "P003",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P028 supplies the extrapolation restriction; P003 identifies the count as missing attachments rather than established absent approvals."
    }
  },
  "signal_basis": {
    "component_id": "C042.signal_basis",
    "value": "The review starts with 14 of 90 sampled orders lacking approval attachments, traces documentary paths for those orders, and tests the proposed routes against other sampled orders.",
    "scope": "Documentary observations within the sampled orders; missing attachments do not establish that approval was absent.",
    "provenance": {
      "refs": [
        {
          "source_id": "P003",
          "role": "SUPPORT"
        },
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish the sample result, its approval-status limitation, and the proposed examination of flagged and other sampled orders."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C042.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The judgment supports a necessary inferential limit and does not depend on establishing an unresolved empirical relation."
    }
  },
  "rationale": "Successful documentary reconstruction can establish facts about sampled orders, but population extrapolation requires a defensible basis connecting the sample to the population. The claim states only that necessary condition and preserves the distinction between missing attachments and approval failures.",
  "uncertainty": "Whether the sampling basis is defensible remains unspecified; this does not prevent judging the stated necessary condition.",
  "anomalies": []
}
